#include <iostream>
#include <cstring>
#include <algorithm>
using namespace std;

const int MOD = 100000000;
int dpF[101][101], dpH[101][101];

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n1, n2, k1, k2;
    while (cin >> n1 >> n2 >> k1 >> k2) {
        memset(dpF, 0, sizeof(dpF));
        memset(dpH, 0, sizeof(dpH));

        for (int i = 1; i <= min(n1, k1); ++i)
            dpF[i][0] = 1;
        for (int j = 1; j <= min(n2, k2); ++j)
            dpH[0][j] = 1;

        for (int i = 1; i <= n1; ++i) {
            for (int j = 1; j <= n2; ++j) {
                long long waysF = 0, waysH = 0;

                for (int len = 1; len <= k1 && len <= i; ++len)
                    waysF += dpH[i - len][j];

                for (int len = 1; len <= k2 && len <= j; ++len)
                    waysH += dpF[i][j - len];

                dpF[i][j] = waysF % MOD;
                dpH[i][j] = waysH % MOD;
            }
        }

        if (n1 == 0 && n2 == 0)
            cout << 1 << '\n';
        else
            cout << (dpF[n1][n2] + dpH[n1][n2]) % MOD << '\n';
    }

    return 0;
}

#include <iostream>
#include <cstring>
using namespace std;

const int MOD = 100000000;

int n1, n2, k1, k2;
int dp[101][101][2][11];

int solve(int f, int h, int last, int consecutive) {
    if (f == n1 && h == n2)
        return 1;

    int &ret = dp[f][h][last][consecutive];
    if (ret != -1)
        return ret;

    ret = 0;

    if (f < n1 && (last != 0 || consecutive < k1)) {
        int nextCount = (last == 0 ? consecutive + 1 : 1);
        ret = (ret + solve(f + 1, h, 0, nextCount)) % MOD;
    }

    if (h < n2 && (last != 1 || consecutive < k2)) {
        int nextCount = (last == 1 ? consecutive + 1 : 1);
        ret = (ret + solve(f, h + 1, 1, nextCount)) % MOD;
    }

    return ret;
}

int main() {
    while (cin >> n1 >> n2 >> k1 >> k2) {
        memset(dp, -1, sizeof(dp));

        int answer = 0;
        if (n1 == 0 && n2 == 0) {
            answer = 1;
        } else {
            if (n1 > 0)
                answer = solve(1, 0, 0, 1);
            if (n2 > 0)
                answer = (answer + solve(0, 1, 1, 1)) % MOD;
        }

        cout << answer << '\n';
    }

    return 0;
}

#include <iostream>
#include <vector>
#include <algorithm>
using namespace std;

const int MOD = 100000000;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n1, n2, k1, k2;
    while (cin >> n1 >> n2 >> k1 >> k2) {
        vector<vector<int>> foot(n1 + 1, vector<int>(n2 + 1));
        vector<vector<int>> horse(n1 + 1, vector<int>(n2 + 1));

        for (int f = 0; f <= n1; ++f) {
            for (int h = 0; h <= n2; ++h) {
                if (f > 0) {
                    if (h == 0 && f <= k1) {
                        foot[f][h] = 1;
                    } else {
                        for (int cnt = 1; cnt <= min(k1, f); ++cnt) {
                            foot[f][h] = (foot[f][h] + horse[f - cnt][h]) % MOD;
                        }
                    }
                }

                if (h > 0) {
                    if (f == 0 && h <= k2) {
                        horse[f][h] = 1;
                    } else {
                        for (int cnt = 1; cnt <= min(k2, h); ++cnt) {
                            horse[f][h] = (horse[f][h] + foot[f][h - cnt]) % MOD;
                        }
                    }
                }
            }
        }

        cout << (foot[n1][n2] + horse[n1][n2]) % MOD << '\n';
    }

    return 0;
}

