#include <algorithm>
using namespace std;

const int MOD = 100000000;
int dp[101][101][2];

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n1, n2, k1, k2;

    while (cin >> n1 >> n2 >> k1 >> k2) {
        fill(&dp[0][0][0], &dp[0][0][0] + 101 * 101 * 2, 0);

        for (int f = 0; f <= n1; ++f) {
            for (int h = 0; h <= n2; ++h) {
                if (f > 0) {
                    if (h == 0 && f <= k1) {
                        dp[f][h][0] = 1;
                    } else {
                        for (int take = 1; take <= min(k1, f); ++take) {
                            dp[f][h][0] =
                                (dp[f][h][0] + dp[f - take][h][1]) % MOD;
                        }
                    }
                }

                if (h > 0) {
                    if (f == 0 && h <= k2) {
                        dp[f][h][1] = 1;
                    } else {
                        for (int take = 1; take <= min(k2, h); ++take) {
                            dp[f][h][1] =
                                (dp[f][h][1] + dp[f][h - take][0]) % MOD;
                        }
                    }
                }
            }
        }

        if (n1 == 0 && n2 == 0)
            cout << 1 << '\n';
        else
            cout << (dp[n1][n2][0] + dp[n1][n2][1]) % MOD << '\n';
    }

    return 0;
}

